def until(cond, timeout=10.0):
    deadline = time.monotonic() + timeout
    while not cond():
        assert time.monotonic() < deadline, "Bedingung nicht rechtzeitig erfüllt"
        time.sleep(0.02)


def model(mid, vision=True, state="enabled"):
    return SimpleNamespace(id=mid, name=mid.title(), policy=SimpleNamespace(state=state),
                           capabilities=SimpleNamespace(supports=SimpleNamespace(vision=vision)),
                           billing=SimpleNamespace(multiplier=1.0),
                           supported_reasoning_efforts=["low", "high"])


class FakeSession:
    def __init__(self, owner, tools):
        self.owner = owner
        self.tools = {t.name: t for t in tools}

    async def send_and_wait(self, prompt, attachments=None, timeout=None):
        self.owner.turns.append((prompt, attachments))
        for name, args in self.owner.script:
            await self.tools[name].handler(ToolInvocation(tool_name=name, arguments=args))
        return SimpleNamespace(data=SimpleNamespace(content="Ich ramme ihn."))

    async def disconnect(self):
        pass

    async def abort(self):
        pass


class FakeClient:
    """Statt Copilot: angemeldet, drei Modelle, jede Runde ruft dieselben Werkzeuge auf."""

    def __init__(self, script=()):
        self.script = list(script)
        self.turns = []
        self.sessions = []

    def __call__(self):
        return self

    async def start(self):
        pass

    async def stop(self):
        pass

    async def get_auth_status(self):
        return SimpleNamespace(isAuthenticated=True, login="naomi", statusMessage="")

    async def list_models(self):
        return [model("sonnet"), model("text-only", vision=False), model("gesperrt", state="disabled")]

    async def create_session(self, **kw):
        self.sessions.append(kw)
        return FakeSession(self, kw["tools"])


