# ---------- Lobby ----------

def test_ai_takes_slot_and_human_moves_over(tmp_path):
    lobby = Lobby(tmp_path / "lobby.json", "admin")
    lobby.join("Kiste")
    assert lobby.reserve_ai(1, "KI · Sonnet") == ("Kiste", 2)
    assert lobby.public()["players"] == [{"slot": 1, "name": "KI · Sonnet", "online": True, "ai": True},
                                         {"slot": 2, "name": "Kiste", "online": False}]
    with pytest.raises(LobbyError) as err:
        lobby.join("Dose")
    assert err.value.code == "full"
    # Nimmt die KI auch Platz 2, hat der Mensch keinen Platz mehr.
    assert lobby.reserve_ai(2, "KI · Opus") == ("Kiste", None)
    lobby.release_ai(1)
    assert lobby.join("Dose")["slot"] == 1


