def test_say_is_trimmed_and_expires(ai_app):
    ai_app.cfg.say_s = 0.2
    ai_app.act("say", {"player": 2, "text": "  Gleich  knallt's! " + "x" * 200})
    text, end = ai_app.says[2]
    assert text.startswith("Gleich knallt's! x") and len(text) == 80
    fight(ai_app)
    t = time.monotonic()
    robot = next(r for r in ai_app.state(t)["robots"] if r["id"] == 2)
    assert robot["say"] == (text if end > t else None)
    assert next(r for r in ai_app.state(end + 0.01)["robots"] if r["id"] == 2)["say"] is None
    ai_app.act("say", {"player": 2, "text": "   "})
    assert 2 not in ai_app.says


def test_pilot_fights_with_image_and_tools(ai_app):
    fake = FakeClient(script=[("set_tactic", {"tactic": "push_out", "side": "left"}),
                              ("say", {"text": "Tschüss!"}),
                              ("ulti", {})])
    ai_app.ai.client_factory = fake
    ai_app.act("ai_slot", {"slot": 2, "model": "sonnet", "steering": "taktik", "robot": ""})
    ai_app.act("ai_mode", {"mode": "mensch-ki"})
    pilot = ai_app.ai.running[2]
    until(lambda: pilot.status == "Bereit, wartet auf den Kampf")
    assert not fake.turns
    fight(ai_app)
    until(lambda: len(fake.turns) >= 2)
    prompt, attachments = fake.turns[0]
    assert "HP" in prompt and "Ulti" in prompt
    assert attachments[0]["mimeType"] == "image/jpeg" and len(attachments[0]["data"]) > 1000
    session = fake.sessions[0]
    assert {t.name for t in session["tools"]} == {"set_tactic", "ulti", "say"}
    assert session["skip_custom_instructions"] is True
    assert pilot.driver.tactic == "push_out" and pilot.driver.side == -1
    robot = next(r for r in ai_app.state(time.monotonic())["robots"] if r["id"] == 2)
    assert robot["ai"] is True and robot["say"] == "Tschüss!"
    assert pilot.comment == "Ich ramme ihn."
    ai_app.act("abort", {})
    until(lambda: pilot.bt.key == STOP)
    ai_app.ai.stop_all(timeout=2.0)
    assert not pilot._thread.is_alive()
    assert pilot.status == "Gestoppt"


def test_ai_slot_cannot_be_kicked_and_players_may_not_switch(client):  # noqa: F811
    app = client.app_state
    app.ai.client_factory = FakeClient()
    login(client, "Kiste")
    player = login(client, "Dose")
    mod = login(client, "mod", "admin")
    assert client.post("/api/ai_mode", json={"mode": "ki-ki"}, headers=player).status_code == 403
    assert client.post("/api/ai_mode", json={"mode": "mensch-ki"}, headers=mod).status_code == 200
    # Dose saß auf Platz 2 und hat nun keinen Platz mehr; Kiste bleibt auf 1.
    players = app.state(0)["lobby"]["players"]
    assert [(p["slot"], p["name"], p.get("ai", False)) for p in players] == [(1, "Kiste", False),
                                                                             (2, "KI", True)]
    assert client.post("/api/kick", json={"slot": 2}, headers=mod).status_code == 400
    app.ai.stop_all(timeout=2.0)


# ---------- Regler ----------

def snap(me_pos, foe_pos, bounds=(0.0, 0.0, 1000.0, 700.0)):
    me = Body(True, np.array(me_pos, np.float32), np.zeros(2, np.float32), 40.0)
    foe = Body(True, np.array(foe_pos, np.float32), np.zeros(2, np.float32), 40.0)
    return Snapshot("fight", 1, True, 1.0, (1000.0, 700.0), bounds, me, foe, "lädt 0 %", [])


def heading(angle):
    h = Heading()
    h.angle, h.key, h.since = angle, "w", 0.0
    return h


def test_heading_comes_from_motion():
    h = Heading()
    me = Body(True, np.zeros(2, np.float32), np.array([0.0, 200.0], np.float32), 40.0)
    h.update("w", me, 0.0)
    h.update("w", me, 0.1)
    assert h.angle is None
    h.update("w", me, 0.3)
    assert h.angle == pytest.approx(math.pi / 2)
    h.update("s", me, 0.4)
    h.update("s", me, 0.7)
    assert h.angle == pytest.approx(-math.pi / 2)
    h.update("d", me, 0.8)
    assert h.angle is None


def test_driver_rams_and_turns_towards_foe():
    d = Driver()
    d.set("ram", 1)
    assert d.key(snap((300, 350), (600, 350)), heading(0.0), 0.0) == "w"
    # Gegner unten (positiver Winkel im Bild) heißt rechts herum drehen, danach ein Stück vor.
    d2 = Driver()
    d2.set("ram", 1)
    assert d2.key(snap((300, 350), (300, 600)), heading(0.0), 0.0) == "d"
    assert d2.key(snap((300, 350), (300, 600)), heading(0.0), 0.5) == "w"
    d3 = Driver()
    d3.set("ram", 1)
    assert d3.key(snap((300, 350), (300, 100)), heading(0.0), 0.0) == "a"


def test_driver_backs_off_from_edge_and_holds():
    d = Driver()
    d.set("ram", 1)
    assert d.key(snap((960, 350), (600, 350)), heading(0.0), 0.0) == "s"
    d.set("hold", 1)
    assert d.key(snap((500, 350), (600, 350)), heading(0.0), 5.0) == STOP
